{"file_path": "E:\testPlatform\code\tools\probe-session.mjs", "content": "// Dev probe: inspect the DSH session log schema for the current workspace.
import { readFileSync, readdirSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { zstdDecompressSync } from 'node:zlib'
import { homedir } from 'node:os'

const DSH_HOME = process.env.DSH_HOME ?? join(homedir(), '.dsh')
const slug = '--E-testPlatform--'
const dir = join(DSH_HOME, 'sessions', slug)
console.log('session dir:', dir, existsSync(dir))
const sessions = readdirSync(dir)
console.log('sessions:', sessions)

const target = process.argv[2] ?? process.env.DSH_SESSION_ID ?? sessions[0]
const file = join(dir, target, 'session.v3.jsonl.zstd')
console.log('file:', file)
const raw = zstdDecompressSync(readFileSync(file)).toString('utf8')
const lines = raw.split('\n').filter((l) => l.trim())
console.log('lines:', lines.length)

const types = new Map()
for (const l of lines) {
  let e
  try { e = JSON.parse(l) } catch { continue }
  const k = e.type ?? e.kind ?? Object.keys(e).join(',')
  types.set(k, (types.get(k) ?? 0) + 1)
}
console.log('--- event types ---')
for (const [k, v] of types) console.log(String(v).padStart(4), k)

console.log('--- first 3 events (raw, trimmed) ---')
for (const l of lines.slice(0, 3)) console.log(l.slice(0, 1500), '\n')

console.log('--- first 12 events (shape) ---')
for (const l of lines.slice(0, 12)) {
  try {
    const e = JSON.parse(l)
    console.log(JSON.stringify(e).slice(0, 700))
  } catch { /* ignore */ }
}
"}

