import { readFileSync } from 'node:fs'
import { createZstdDecompress, zstdDecompressSync } from 'node:zlib'
import { join } from 'node:path'
import { homedir } from 'node:os'

const DSH_HOME = process.env.DSH_HOME ?? join(homedir(), '.dsh')
const target = process.argv[2] ?? process.env.DSH_SESSION_ID
const file = join(DSH_HOME, 'sessions', '--E-testPlatform--', target, 'session.v3.jsonl.zstd')
const buf = readFileSync(file)
console.log('bytes:', buf.length)

// count zstd frames (magic 28 B5 2F FD)
let frames = 0
for (let i = 0; i + 4 <= buf.length; i++) {
  if (buf[i] === 0x28 && buf[i + 1] === 0xb5 && buf[i + 2] === 0x2f && buf[i + 3] === 0xfd) frames++
}
console.log('magic occurrences:', frames)

const one = zstdDecompressSync(buf)
console.log('single-call decompressed bytes:', one.length)

const stream = createZstdDecompress()
const chunks = []
stream.on('data', (c) => chunks.push(c))
stream.on('error', (e) => console.log('stream error:', e.message))
stream.on('end', () => {
  const text = Buffer.concat(chunks).toString('utf8')
  const lines = text.split('\n').filter((l) => l.trim())
  console.log('stream decompressed bytes:', Buffer.byteLength(text), 'lines:', lines.length)
  const types = new Map()
  for (const l of lines) {
    let e
    try { e = JSON.parse(l) } catch { console.log('BAD LINE:', l.slice(0, 200)); continue }
    const k = e.type ?? '?'
    types.set(k, (types.get(k) ?? 0) + 1)
  }
  for (const [k, v] of types) console.log(String(v).padStart(4), k)
  for (const l of lines.slice(1, 6)) console.log('EVENT>', l.slice(0, 900))
})
stream.end(buf)

