  if (Array.isArray(value)) return value.map((v) => interpolateDeep(v, vars, missing))
  if (value && typeof value === 'object') {
    const out = {}
    for (const [k, v] of Object.entries(value)) out[k] = interpolateDeep(v, vars, missing)
    return out
  }
