  name: 'Web：兜底页面标题可见',
  type: 'web',
  tags: ['web'],
  steps: [
    { name: '打开首页', action: { type: 'goto', url: '/' }, screenshot: true,
      assertions: [{ type: 'urlContains', op: 'contains', expected: '127.0.0.1' }] },
    { name: '检查标题', action: { type: 'waitForSelector', selector: 'h1' },
      assertions: [
        { type: 'elementVisible', op: 'truthy', selector: 'h1' },
        { type: 'elementText', op: 'contains', selector: 'h1', expected: '测试平台' },
      ] },
  ],
})
console.log('case:', testCase.status, testCase.data.id ?? testCase.data.error)

const run = await post('/api/runs', { projectId: project.data.id, name: 'Web 冒烟执行' })
console.log('run:', run.data.runId ?? run.data.error)

let detail = null
for (let i = 0; i < 200; i++) {
  const res = await j(`/api/runs/${run.data.runId}`)
  detail = res.data
  if (detail.status !== 'running') break
  await new Promise((r) => setTimeout(r, 400))
}
console.log('status:', detail.status, JSON.stringify(detail.summary))
for (const r of detail.results) {
  console.log(`  ${r.status} ${r.name} (${r.durationMs}ms) 截图=${JSON.stringify(r.screenshots)}`)
