{"content": "// 临时验证：独立检查示例被测软件的行为与缺陷。用完后删除。
const BASE = `http://127.0.0.1:${process.env.PORT ?? 4598}`
const j = async (path, init) => {
  const res = await fetch(BASE + path, init)
  let data = null
  try { data = await res.json() } catch { data = null }
  return { status: res.status, data }
}
const post = (path, body, headers = {}) => j(path, {
  method: 'POST',
  headers: { 'content-type': 'application/json', ...headers },
  body: JSON.stringify(body ?? {}),
})

const health = await j('/api/health')
console.log('health:', health.status, JSON.stringify(health.data))

const login = await post('/api/login', { username: 'admin', password: '123456' })
console.log('login ok:', login.status, JSON.stringify(login.data).slice(0, 160))
const token = login.data?.token

const badLogin = await post('/api/login', { username: 'admin', password: 'wrong' })
console.log('login bad:', badLogin.status, JSON.stringify(badLogin.data))

const products = await j('/api/products')
console.log('products:', products.status, 'total=', products.data?.total)
console.log('  items:', JSON.stringify(products.data?.items ?? []).slice(0, 400))
const first = products.data?.items?.[0]
const cheap = (products.data?.items ?? []).find((p) => p.price < 99)

const search = await j('/api/products?keyword=' + encodeURIComponent('耳机'))
console.log('search 耳机:', search.status, 'total=', search.data?.total)

const notFound = await j('/api/products/not-exist-id')
console.log('404 case:', notFound.status, JSON.stringify(notFound.data))

const auth = { Authorization: `Bearer ${token}` }
console.log('--- 缺陷 1：小额订单运费 ---')
const order1 = await post('/api/cart/checkout', { items: [{ productId: cheap?.id, qty: 1 }] }, auth)
console.log(' status:', order1.status, JSON.stringify(order1.data))

console.log('--- 缺陷 2：优惠券折扣基准 ---')
const order2 = await post('/api/cart/checkout', { items: [{ productId: cheap?.id, qty: 1 }], couponCode: 'SAVE10' }, auth)
console.log(' status:', order2.status, JSON.stringify(order2.data))

console.log('--- 缺陷 3：库存校验 ---')
const order3 = await post('/api/cart/checkout', { items: [{ productId: first?.id, qty: 9999 }] }, auth)
console.log(' status:', order3.status, JSON.stringify(order3.data).slice(0, 200))

console.log('--- 未登录下单应为 401 ---')
const order4 = await post('/api/cart/checkout', { items: [{ productId: first?.id, qty: 1 }] })
console.log(' status:', order4.status, JSON.stringify(order4.data))

console.log('--- 页面 ---')
for (const path of ['/', '/shop']) {
  const res = await fetch(BASE + path, { redirect: 'manual' })
  const html = await res.text()
  console.log(` ${path}: ${res.status} ${html.length} bytes`, /data-testid="(username|login-btn|product-list)"/.exec(html)?.[1] ?? '')
}
const shop = await fetch(BASE + '/shop?token=' + token)
const shopHtml = await shop.text()
for (const id of ['product-list', 'product-item', 'add-to-cart', 'search-input', 'search-btn', 'cart-count', 'cart-subtotal', 'coupon-input', 'checkout-btn', 'order-total']) {
  if (!shopHtml.includes(`data-testid="${id}"`)) console.log(`  ⚠️ 缺少选择器: ${id}`)
}
console.log(' shop 页面检查完成:', shop.status, shopHtml.length, 'bytes')
", "file_path": "E:\testPlatform\code\tools\_smoke-demo.mjs"}

