    const assertion = (healthCase.steps?.[0]?.assertions ?? [])[0]
    check('健康检查用例断言通过', healthCase.status === 'passed', assertion ? assertion.message : '无用例')
  } else {
    check('健康检查用例存在', false, '未找到名称含「健康」的用例')
