  const selfTest = await runSelfTest({
    platformPort: PLATFORM_PORT,
    demoPort: DEMO_PORT,
    startServers: true,
    keepServers: true,
  })

  let ui = null
  if (SKIP_UI) {
    console.log('\n（--skip-ui：跳过界面自测）')
  } else if (!existsSync(join(CODE_ROOT, 'web', 'dist', 'index.html'))) {
