const base='http://127.0.0.1:4519';
(async()=>{
  const db=JSON.parse(require('fs').readFileSync('data/db.json','utf8'));
  const p=db.projects.find(x=>db.cases.filter(c=>c.projectId===x.id).length===11)||db.projects[0];
  const start=await (await fetch(base+'/api/runs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({projectId:p.id,tags:['smoke'],name:'预检 · smoke 用例'})})).json();
  if(start.error){console.log('启动失败:',start.error);return}
  let run=null;
  for(let i=0;i<120;i++){ await new Promise(r=>setTimeout(r,500)); run=await (await fetch(base+'/api/runs/'+start.runId)).json(); if(run.status!=='running')break }
  console.log('项目:',p.name,'| 状态:',run.status,'| 通过',run.summary.passed,'失败',run.summary.failed,'异常',run.summary.error);
  for(const r of run.results) console.log(' ', r.status==='passed'?'PASS':'FAIL', '['+r.type+']', r.name, '('+r.durationMs+'ms)', (r.screenshots||[]).length?'截图'+r.screenshots.length+'张':'');
  const web=run.results.filter(r=>r.type==='web');
  console.log(web.length?('Web 用例在本次运行中执行正常: '+web.map(r=>r.status).join(',')):'本次无 Web 用例');
})().catch(e=>{console.error('预检异常:',e.message);process.exit(1)})
"", "description": "Pre-flight smoke run including a web case"}

